import {SCALES,VERSION} from './instrument.mjs';
import {ROLE_INFO,CONTEXT_ITEMS,PRACTICES,PRACTICE_CHOICES,INTIMACY_VERSION} from './extensions-data.mjs';
export const COMPARISON_VERSION='comparison-1.0.0';
const numeric=v=>typeof v==='number'&&Number.isFinite(v)&&v>=1&&v<=5;
export function compareProfiles(a,b){
  const common=(a.scopes||[]).filter(x=>(b.scopes||[]).includes(x));
  const result={common,personality:[],roles:[],context:[],practices:[],warnings:[],same:a.id===b.id};
  const ipipOK=a.ipipVersion===VERSION&&b.ipipVersion===VERSION;
  const intimateOK=a.intimacyVersion===INTIMACY_VERSION&&b.intimacyVersion===INTIMACY_VERSION;
  if(common.includes('personality')&&!ipipOK)result.warnings.push('Osobnost používá rozdílnou nebo nepodporovanou verzi otázek. Hodnoty nesrovnáváme.');
  if(common.some(s=>s!=='personality')&&!intimateOK)result.warnings.push('Intimní část používá rozdílnou nebo nepodporovanou verzi. Hodnoty nesrovnáváme.');
  const rows=(items,part)=>items.map(x=>{const av=a[part]?.[x.id],bv=b[part]?.[x.id],complete=numeric(av)&&numeric(bv);return {id:x.id,name:x.name||x.text,a:numeric(av)?av:null,b:numeric(bv)?bv:null,complete,delta:complete?Math.round(Math.abs(av-bv)*100)/100:null};});
  if(common.includes('personality')&&ipipOK)result.personality=rows(SCALES,'personality');
  if(common.includes('roles')&&intimateOK)result.roles=rows(ROLE_INFO,'roles');
  if(common.includes('context')&&intimateOK)result.context=rows(CONTEXT_ITEMS,'context');
  if(common.includes('practices')&&intimateOK)result.practices=PRACTICES.map(x=>{
    const av=a.practices?.[x.id],bv=b.practices?.[x.id],known=v=>['yes','talk','no'].includes(v);
    const kind=av==='no'||bv==='no'?'boundary':!known(av)||!known(bv)?'unknown':av==='yes'&&bv==='yes'?'shared':'talk';
    return {id:x.id,name:x.name,a:PRACTICE_CHOICES[av]||'Neuvedeno',b:PRACTICE_CHOICES[bv]||'Neuvedeno',kind};
  });
  return result;
}
export const comparisonLabels={shared:'Oba uvedli zájem',boundary:'Hranice k respektování',talk:'K rozhovoru',unknown:'Bez závěru'};
export function mapTemperament(p){if(!numeric(p?.E)||!numeric(p?.S))return 'Neúplné škály';if((p.E>2.5&&p.E<3.5)||(p.S>2.5&&p.S<3.5))return 'Smíšená / středová oblast';return p.E>=3.5?(p.S>=3.5?'Sangvinik':'Cholerik'):(p.S>=3.5?'Flegmatik':'Melancholik');}
export function comparisonSources(){return `<div class="wrap narrow page-head"><span class="eyebrow">ZDROJE / POROVNÁNÍ</span><h1>Dva profily.<br><em>Žádná věštba vztahu.</em></h1><p class="lead">Porovnáváme vaše vlastní odpovědi. Shoda ani rozdíl samy neurčují, jak vám spolu bude.</p></div><article class="wrap narrow reading"><section><h2>Co lze vyčíst</h2><p>U stejné verze dotazníku ukazujeme oba průměry a jejich absolutní rozdíl v bodech stupnice 1–5. U aktivit ukazujeme přímo vaše volby. Výsledek může pomoci pojmenovat témata pro rozhovor, nikoli stanovit kvalitu či budoucnost vztahu.</p><p>Vlastní český překlad IPIP-50 i naše intimní otázky jsou dosud nevalidované. Malý rozdíl může být ovlivněn nejistotou měření, odlišným chápáním otázky a aktuální situací. Nemáme údaje pro intervaly spolehlivosti nebo statistickou významnost rozdílu.</p></section><section><h2>Podobnost povahy není skóre kompatibility</h2><div class="source-card"><h3>Dyrenforth, Kashy, Donnellan & Lucas (2010)</h3><p><cite>Predicting relationship and life satisfaction from personality in nationally representative samples from three countries: the relative importance of actor, partner, and similarity effects.</cite> JPSP, 99(4), 690–702.</p><p>Ve třech národních souborech manželských párů vysvětlovala podobnost po zohlednění osobnosti obou partnerů méně než 0,5 % variability spokojenosti. To nepodporuje jednoduché párování podle podobnosti.</p><a href="https://pubmed.ncbi.nlm.nih.gov/20718544/" target="_blank" rel="noopener noreferrer">Původní studie · DOI 10.1037/a0020385 ↗</a></div><div class="source-card"><h3>Weidmann et al. (2023)</h3><p><cite>Trait and facet personality similarity and relationship and life satisfaction in romantic couples.</cite> Journal of Research in Personality, 104, 104378.</p><p>U 1 294 párů žena–muž nebyla podobnost rysů ani jemnějších aspektů robustně spojena se vztahovou a životní spokojeností. Neznamená to, že osobnost nehraje roli, nebo že jsou rozdíly vždy prospěšné.</p><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10312100/" target="_blank" rel="noopener noreferrer">Plný text · DOI 10.1016/j.jrp.2023.104378 ↗</a></div></section><section><h2>Intimita: podklad pro rozhovor</h2><div class="source-card"><h3>MacNeil & Byers (2009)</h3><p><cite>Role of sexual self-disclosure in the sexual satisfaction of long-term heterosexual couples.</cite> Journal of Sex Research, 46(1), 3–14.</p><p>Studie 104 dlouhodobých heterosexuálních párů zkoumala sdělování sexuálních preferencí v souvislosti se spokojeností. Podporuje téma komunikace, nikoli výpočet sexuální kompatibility nebo předpověď pro konkrétní pár.</p><a href="https://pubmed.ncbi.nlm.nih.gov/19012061/" target="_blank" rel="noopener noreferrer">Původní studie · DOI 10.1080/00224490802398399 ↗</a></div><p>Rozdílný zájem o tutéž roli nemusí znamenat konflikt. Dominantní a submisivní nebo sadistickou a masochistickou roli automaticky neprohlašujeme za vhodný pár. Nízký zájem o vlastní roli neříká, zda ji člověk chce u partnera.</p></section><section><h2>Na čem stojí rozbor a výběr AI</h2><p>Úplný rozbor sestavuje web podle pevných pravidel. U každé společně zpřístupněné položky zachovává hodnotu profilu A i B, přesné znění voleb a vysvětlení významu. Zahrnuje shody, rozdíly, nejbližší číselné hodnoty, otevřené možnosti i hranice. Nepřeskakuje položky podle pořadí největších rozdílů.</p><p>Za přesnou číselnou shodu označujeme pouze rovnost hodnot. Nejbližší hodnoty jsou minimum absolutního rozdílu v dané kategorii, nikoli ověřený práh psychologické podobnosti. U aktivit rozlišujeme výslovný zájem obou, možnost rozhovoru, hranici a neurčenou odpověď. „Možná / chci probrat“ nikdy nepřevádíme na potvrzený zájem. Samostatná aktivita neznamená společné přání páru.</p><p>Texty výkladu a otázek jsou předem napsané pro jednotlivá témata. Místní AI smí pouze vybrat identifikátor otázky z každé dostupné skupiny: ke společnému bodu a k odlišné či otevřené odpovědi; pokud není číselná shoda, může být samostatně zahrnuta otázka k nejbližším hodnotám. Odpověď modelu s vlastním textem nebo nepovoleným identifikátorem odmítneme. AI tedy nepíše tvrzení o lidech a nemůže změnit přiřazení hodnot A/B.</p><p>Při nedostupnosti nebo neplatné odpovědi modelu zůstává stejný úplný rozbor a otázky vybere web. Hranice a neurčené preference se do výběru AI neposílají. Výběr otázek není určením nejdůležitějšího vztahového tématu.</p><p>Jde o vlastní nevalidovaný způsob vysvětlení, nikoli validovaný psychologický posudek. Uvedené studie nepředstavují validaci našich textů ani výběru AI. Přesné přiřazení odpovědí nezvyšuje přesnost dotazníků a nepředpovídá spokojenost, chování nebo souhlas. Nesouhlas s výkladem není chyba člověka.</p></section><section><h2>Naše přesná pravidla</h2><ul><li>Porovnáváme jen kategorie zpřístupněné oběma lidmi a stejnou podporovanou verzi.</li><li>Big Five: pouze úplné škály, dvě hodnoty a |A − B|. Žádné procento shody, normy ani práh „významného“ rozdílu.</li><li>Temperament je doplňkový historický popis dvou už použitých škál. Nezapočítává se znovu.</li><li>Role: dvě číselné odpovědi pro průměr, obě hodnoty vedle sebe. Kontext: jednotlivé odpovědi bez souhrnného skóre.</li><li>„Láká mě“ u obou → oba uvedli zájem. Pokud někdo uvede „Nechci“, připomeneme hranici bez ohledu na druhou volbu.</li><li>„Možná / chci probrat“ s další známou kladnou nebo možnou volbou → k rozhovoru. „Nevím“, soukromá, nevyplněná či neúplná odpověď není shoda ani neshoda; chybějící hodnoty nedoplňujeme.</li></ul><p>Tato pravidla jsou vlastní transparentní zobrazení webu, nikoli validovaný algoritmus převzatý ze studií. Verze: ${COMPARISON_VERSION}. Zkoumané soubory nepostihují všechny druhy vztahů.</p><p><strong>Společný zájem není souhlas.</strong> „Nechci“ není námět k přemlouvání. „Možná“, „Nevím“ a vynechání nejsou souhlas. Přání se domlouvají v konkrétní situaci a mohou se měnit.</p></section><div class="bottom-callout"><a class="button" href="#porovnani">Porovnat dva profily →</a></div></article>`;}
